import{_ as n,o as a,c as s,ai as t}from"./chunks/framework.BxxKhjs3.js";const o="/pub-blog/assets/image-20260406150738482.BMJifRju.png",p="/pub-blog/assets/image-20260406151002787.WHEEGpYO.png",l="/pub-blog/assets/image-20260406151500815.CYu1Aq0F.png",i="/pub-blog/assets/image-20260406151625512.B9FVXwqm.png",d="/pub-blog/assets/image-20260406151926697.CTtQ_T7P.png",r="/pub-blog/assets/image-20260404153811993.DCT8eByA.png",E=JSON.parse('{"title":"Token 燃烧器 Claude Code Agent Teams","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/token燃烧器 Claude Code  Agent Teams/token燃烧器 Claude Code  Agent Teams.md","filePath":"AI人工智能/token燃烧器 Claude Code  Agent Teams/token燃烧器 Claude Code  Agent Teams.md","lastUpdated":1775460108000,"__rawMarkdown":"# Token 燃烧器 Claude Code Agent Teams \\n\\n\\n\\n## 背景\\n\\n最近在玩小龙虾编写小说，目前电脑上有4部小说，其中一部已经完结，剩下3部想要摆烂，赶紧写完到终结，后续碰碰运气坚持发\\n\\n布即可。\\n\\n由于本身是做技术的，我电脑上也安装了多个AI工具，其中包括 大名鼎鼎的  **Claude Code**。\\n\\n于是就利用 **Claude Code**  提供  **Agent Teams** 能力，一口气同步续写4部小说吧。\\n\\n---\\n\\n## 这功能到底能干啥\\n\\n多个 **Claude Code** 实例作为一个团队一起工作，具有共享任务、代理间消息传递和集中管理。\\n\\nAgent teams 让你协调多个 Claude Code 实例一起工作。一个会话充当团队负责人，协调工作、分配任务和综合结果。队友独立工\\n\\n作，每个都在自己的 **context window** 中，并直接相互通信。\\n\\n![](assets/image-20260406150738482.png)\\n\\n那么我可以设计一个负责人，然后创建3个队友。每一个队长负责续写一篇小说，当续写完毕后主动通知lead即可。\\n\\n---\\n\\n## 为什么叫「Token 燃烧器」\\n\\n用过的人都知道，这功能烧起 token 来毫不手软。因为它是并行的，所以效率高高高。万少这里是使用阿里百炼的 `codingplan` 套餐，用完了等5个小时重置即可。\\n\\n![](assets/image-20260406151002787.png)\\n\\n## 创建 Agent Teams\\n\\n> Agent teams 需要 Claude Code v2.1.32 或更高版本\\n>\\n> Agent teams 是实验性功能，默认禁用。\\n>\\n> 通过将 `CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS` 添加到你的 [settings.json](https://code.claude.com/docs/zh-CN/settings) 或环境变量来启用它们。\\n\\n开启 **Agent Teams**\\n\\n```json\\n  \\"env\\": {\\n    \\"CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS\\": \\"1\\"\\n  },\\n```\\n\\n创建 **Agent Teams**\\n\\n```\\n 帮我创建一个agent teams，里面有3个队友，分别负责目录下的\\n  极夜序列、我靠杀前夫刷经验、坐棺匠三部小说的续写任务。直到完毕，完毕的标准需要各自的队友\\n  根据已有的大纲或者剧情进行判断。这三个队友使用的模型必须和当前claude的默认配置一致，也是 Opus\\n```\\n\\n**这里有个地方需要特别注意，你如果也是像万少一样使用类似阿里百炼平台这些聚合平台的话，你需要明确给队友指定model，否则它们默认会使用  Claude Sonnet 系列，这样导致队友的模型配置失败。**\\n\\n你指定的model 需要是 Haiku、Sonnet、Opus 等关键字！！！\\n\\n![](assets/image-20260406151500815.png)\\n\\n## 切换队友\\n\\n在终端中，可以输入 `shift +  ⬇️`  来切换队友，然后直接和它通话，也方便关注当前队友的配置是否正确。\\n\\n![](assets/image-20260406151625512.png)\\n\\n\\n\\n## Agent Teams 的生命周期是一次会话\\n\\n需要特别注意的是，你所创建的Agent Teams 会在你退出终端后，整个Teams便会解散，所以需要尽量在一次会话中把任务推进完\\n\\n毕。要不然怎么说是**token燃烧器**呢。\\n\\n\\n\\n## 关闭队友和清理团队\\n\\n当你完成任务后，可以直接通过自然语言的方式来关闭队友和清理队伍。\\n\\n当清理团队后，claude 配置目录下的teams也会清空。\\n\\n![](assets/image-20260406151926697.png)\\n\\n## 引用地址\\n\\n\\n\\n[协调 Claude Code 会话团队](https://code.claude.com/docs/zh-CN/agent-teams#%E5%88%86%E9%85%8D%E5%92%8C%E8%AE%A4%E9%A2%86%E4%BB%BB%E5%8A%A1)\\n\\n\\n\\n万少建立了一个专门讨论小龙虾OpenClaw的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n目前人已经超过**200**人了，私聊我进群。\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/image-20260404153811993.DCT8eByA.png)\\n\\n"}'),g={name:"AI人工智能/token燃烧器 Claude Code  Agent Teams/token燃烧器 Claude Code  Agent Teams.md"};function m(c,e,u,h,C,A){return a(),s("div",null,[...e[0]||(e[0]=[t("",42)])])}const _=n(g,[["render",m]]);export{E as __pageData,_ as default};
